CREATE TABLE app_setting ( key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at INTEGER NOT NULL ) STRICT, WITHOUT ROWID;
CREATE TABLE assignee_change ( issue_id INTEGER NOT NULL REFERENCES issue(id) ON DELETE CASCADE, history_id TEXT NOT NULL, changed_at INTEGER NOT NULL, from_account_id TEXT, to_account_id TEXT, PRIMARY KEY (issue_id, history_id) ) STRICT, WITHOUT ROWID;
CREATE INDEX assignee_change_time ON assignee_change(issue_id, changed_at);
CREATE TABLE attachment ( id INTEGER PRIMARY KEY, issue_id INTEGER NOT NULL REFERENCES issue(id) ON DELETE CASCADE, source_id TEXT NOT NULL, media_file_id TEXT, name TEXT NOT NULL, mime TEXT NOT NULL DEFAULT 'application/octet-stream', bytes INTEGER NOT NULL DEFAULT 0, author_account_id TEXT, created_at INTEGER NOT NULL, is_image INTEGER NOT NULL DEFAULT 0 CHECK (is_image IN (0,1)), width INTEGER, height INTEGER, thumb_path TEXT, file_path TEXT, cached_bytes INTEGER NOT NULL DEFAULT 0, last_viewed_at INTEGER, evicted_at INTEGER, fetch_error TEXT, removed_at INTEGER, UNIQUE (issue_id, source_id) ) STRICT;
CREATE INDEX attachment_lru ON attachment(last_viewed_at) WHERE file_path IS NOT NULL;
CREATE INDEX attachment_media ON attachment(media_file_id) WHERE media_file_id IS NOT NULL;
CREATE TABLE board ( connection_id INTEGER NOT NULL REFERENCES connection(id) ON DELETE CASCADE, id TEXT NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL, space_id TEXT, source_meta TEXT NOT NULL DEFAULT '{}', config_fetched_at INTEGER, fetched_at INTEGER NOT NULL, PRIMARY KEY (connection_id, id) ) STRICT, WITHOUT ROWID;
CREATE TABLE board_column ( connection_id INTEGER NOT NULL, board_id TEXT NOT NULL, position INTEGER NOT NULL, name TEXT NOT NULL, PRIMARY KEY (connection_id, board_id, position), FOREIGN KEY (connection_id, board_id) REFERENCES board(connection_id, id) ON DELETE CASCADE ) STRICT, WITHOUT ROWID;
CREATE TABLE board_column_status ( connection_id INTEGER NOT NULL, board_id TEXT NOT NULL, position INTEGER NOT NULL, status_id TEXT NOT NULL, PRIMARY KEY (connection_id, board_id, status_id), FOREIGN KEY (connection_id, board_id, position) REFERENCES board_column(connection_id, board_id, position) ON DELETE CASCADE ) STRICT, WITHOUT ROWID;
CREATE INDEX board_space ON board(connection_id, space_id);
CREATE TABLE comment ( issue_id INTEGER NOT NULL REFERENCES issue(id) ON DELETE CASCADE, comment_id TEXT NOT NULL, author_account_id TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL DEFAULT 0, body_adf TEXT, visibility_type TEXT CHECK (visibility_type IN ('role','group')), visibility_value TEXT, deleted_at INTEGER, PRIMARY KEY (issue_id, comment_id) ) STRICT, WITHOUT ROWID;
CREATE INDEX comment_time ON comment(issue_id, created_at);
CREATE TABLE connection ( id INTEGER PRIMARY KEY, source TEXT NOT NULL DEFAULT 'jira', base_url TEXT NOT NULL UNIQUE, account TEXT NOT NULL, account_id TEXT, display_name TEXT, auth_state TEXT NOT NULL DEFAULT 'unknown' CHECK (auth_state IN ('unknown','ok','invalid','missing')), verified_at INTEGER, source_meta TEXT NOT NULL DEFAULT '{}', dev_activity_state TEXT NOT NULL DEFAULT 'unknown' CHECK (dev_activity_state IN ('unknown','ok','unavailable')), dev_activity_checked_at INTEGER, created_at INTEGER NOT NULL ) STRICT;
CREATE TABLE dev_commit ( issue_id INTEGER NOT NULL REFERENCES issue(id) ON DELETE CASCADE, commit_id TEXT NOT NULL, repo TEXT NOT NULL DEFAULT '', authored_at INTEGER NOT NULL, is_merge INTEGER NOT NULL DEFAULT 0 CHECK (is_merge IN (0,1)), PRIMARY KEY (issue_id, commit_id) ) STRICT, WITHOUT ROWID;
CREATE INDEX dev_commit_time ON dev_commit(issue_id, authored_at);
CREATE TABLE dev_pr_event ( issue_id INTEGER NOT NULL REFERENCES issue(id) ON DELETE CASCADE, pr_key TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('OPEN','MERGED','DECLINED','UNKNOWN')), at INTEGER NOT NULL, title TEXT, branch TEXT, PRIMARY KEY (issue_id, pr_key, status, at) ) STRICT, WITHOUT ROWID;
CREATE INDEX dev_pr_event_time ON dev_pr_event(issue_id, at);
CREATE TABLE field_def ( connection_id INTEGER NOT NULL REFERENCES connection(id) ON DELETE CASCADE, field_id TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('text','paragraph','number','date','datetime','url','option','options','cascade', 'user','users','group','groups','version','versions','component','components','labels','project','team','unknown')), custom INTEGER NOT NULL DEFAULT 0 CHECK (custom IN (0,1)), custom_type TEXT, schema_json TEXT NOT NULL DEFAULT '{}', fetched_at INTEGER NOT NULL, PRIMARY KEY (connection_id, field_id) ) STRICT, WITHOUT ROWID;
CREATE TABLE flag_change ( issue_id INTEGER NOT NULL REFERENCES issue(id) ON DELETE CASCADE, history_id TEXT NOT NULL, changed_at INTEGER NOT NULL, flagged INTEGER NOT NULL CHECK (flagged IN (0,1)), PRIMARY KEY (issue_id, history_id) ) STRICT, WITHOUT ROWID;
CREATE TABLE issue ( id INTEGER PRIMARY KEY, connection_id INTEGER NOT NULL REFERENCES connection(id) ON DELETE CASCADE, source_id TEXT NOT NULL, key TEXT NOT NULL, space_id TEXT NOT NULL, summary TEXT NOT NULL, issue_type_id TEXT NOT NULL, status_id TEXT NOT NULL, assignee_account_id TEXT, flagged INTEGER NOT NULL DEFAULT 0 CHECK (flagged IN (0,1)), rank TEXT, parent_key TEXT, sprint_ids TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, resolved_at INTEGER, comment_total INTEGER NOT NULL DEFAULT 0, dev_fingerprint TEXT, dev_checked_at INTEGER, hydrated_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL, removed_at INTEGER, source_meta TEXT NOT NULL DEFAULT '{}' ) STRICT;
CREATE INDEX issue_assignee ON issue(assignee_account_id);
CREATE TABLE issue_content ( issue_id INTEGER PRIMARY KEY REFERENCES issue(id) ON DELETE CASCADE, description_adf TEXT, environment_adf TEXT, watchers INTEGER NOT NULL DEFAULT -1, content_hash TEXT NOT NULL, updated_at INTEGER NOT NULL ) STRICT;
CREATE TABLE issue_field_value ( issue_id INTEGER NOT NULL REFERENCES issue(id) ON DELETE CASCADE, field_id TEXT NOT NULL, kind TEXT NOT NULL, value_json TEXT NOT NULL, PRIMARY KEY (issue_id, field_id) ) STRICT, WITHOUT ROWID;
CREATE TABLE issue_gen ( id INTEGER PRIMARY KEY CHECK (id = 1), n INTEGER NOT NULL );
CREATE TRIGGER issue_gen_delete AFTER DELETE ON issue BEGIN INSERT INTO issue_gen (id, n) VALUES (1, 1) ON CONFLICT (id) DO UPDATE SET n = n + 1; END;
CREATE TRIGGER issue_gen_insert AFTER INSERT ON issue BEGIN INSERT INTO issue_gen (id, n) VALUES (1, 1) ON CONFLICT (id) DO UPDATE SET n = n + 1; END;
CREATE TRIGGER issue_gen_update AFTER UPDATE OF key, summary, status_id ON issue WHEN old.key IS NOT new.key OR old.summary IS NOT new.summary OR old.status_id IS NOT new.status_id BEGIN INSERT INTO issue_gen (id, n) VALUES (1, 1) ON CONFLICT (id) DO UPDATE SET n = n + 1; END;
CREATE UNIQUE INDEX issue_key ON issue(connection_id, key);
CREATE TABLE issue_link ( issue_id INTEGER NOT NULL REFERENCES issue(id) ON DELETE CASCADE, link_id TEXT NOT NULL, relation TEXT NOT NULL CHECK (relation IN ('link','subtask')), label TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL DEFAULT 0, other_source_id TEXT NOT NULL, other_key TEXT NOT NULL, other_summary TEXT NOT NULL DEFAULT '', other_status_id TEXT, other_type_id TEXT, other_assignee_account_id TEXT, PRIMARY KEY (issue_id, link_id) ) STRICT, WITHOUT ROWID;
CREATE INDEX issue_link_other ON issue_link(other_source_id);
CREATE UNIQUE INDEX issue_source ON issue(connection_id, source_id);
CREATE TABLE issue_type ( connection_id INTEGER NOT NULL REFERENCES connection(id) ON DELETE CASCADE, id TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('story','bug','task','spike','subtask','epic','other')), PRIMARY KEY (connection_id, id) ) STRICT, WITHOUT ROWID;
CREATE TABLE person ( connection_id INTEGER NOT NULL REFERENCES connection(id) ON DELETE CASCADE, account_id TEXT NOT NULL, display_name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)), account_type TEXT, fetched_at INTEGER NOT NULL, PRIMARY KEY (connection_id, account_id) ) STRICT, WITHOUT ROWID;
CREATE TABLE sink ( id INTEGER PRIMARY KEY, kind TEXT NOT NULL, name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 80), standup_id INTEGER REFERENCES standup(id) ON DELETE CASCADE, config TEXT NOT NULL DEFAULT '{}', send_on TEXT NOT NULL DEFAULT 'manual' CHECK (send_on IN ('manual','after_sync')), enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL ) STRICT;
CREATE TABLE sink_outbox ( id INTEGER PRIMARY KEY, sink_id INTEGER NOT NULL REFERENCES sink(id) ON DELETE CASCADE, standup_id INTEGER NOT NULL REFERENCES standup(id) ON DELETE CASCADE, cause TEXT NOT NULL CHECK (cause IN ('manual','after_sync')), payload_kind TEXT NOT NULL CHECK (payload_kind IN ('current','range')), as_of INTEGER, range_from TEXT, range_to TEXT, idempotency_key TEXT NOT NULL UNIQUE, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','delivering','delivered','failed','dead')), attempts INTEGER NOT NULL DEFAULT 0, last_error_code TEXT, last_error TEXT, receipt TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, delivered_at INTEGER ) STRICT;
CREATE INDEX sink_outbox_pending ON sink_outbox(sink_id, status, id);
CREATE TABLE space ( connection_id INTEGER NOT NULL REFERENCES connection(id) ON DELETE CASCADE, id TEXT NOT NULL, key TEXT NOT NULL, name TEXT NOT NULL, source_meta TEXT NOT NULL DEFAULT '{}', fetched_at INTEGER NOT NULL, PRIMARY KEY (connection_id, id) ) STRICT, WITHOUT ROWID;
CREATE INDEX space_key ON space(connection_id, key);
CREATE TABLE sprint ( connection_id INTEGER NOT NULL REFERENCES connection(id) ON DELETE CASCADE, id TEXT NOT NULL, board_id TEXT NOT NULL, name TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('future','active','closed')), start_at INTEGER, end_at INTEGER, complete_at INTEGER, fetched_at INTEGER NOT NULL, PRIMARY KEY (connection_id, id) ) STRICT, WITHOUT ROWID;
CREATE INDEX sprint_board ON sprint(connection_id, board_id, state);
CREATE TABLE standup ( id INTEGER PRIMARY KEY, connection_id INTEGER REFERENCES connection(id) ON DELETE SET NULL, name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 80), position INTEGER NOT NULL, space_id TEXT, space_key TEXT, space_name TEXT, board_id TEXT, board_name TEXT, board_type TEXT CHECK (board_type IN ('scrum','kanban')), board_meta TEXT NOT NULL DEFAULT '{}', scope TEXT NOT NULL DEFAULT 'sprint' CHECK (scope IN ('sprint','board')), extra_filter TEXT NOT NULL DEFAULT '', extra_filter_ok INTEGER CHECK (extra_filter_ok IN (0,1)), extra_filter_error TEXT, rev INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, CHECK (board_type <> 'kanban' OR scope = 'board') ) STRICT;
CREATE TABLE "standup_column_map" ( standup_id INTEGER NOT NULL REFERENCES standup(id) ON DELETE CASCADE, column_name TEXT NOT NULL, position INTEGER NOT NULL, lane TEXT NOT NULL CHECK (lane IN ('backlog','todo','prog','review','qa','done','hidden') OR (lane GLOB 'c[1-9]*' AND lane NOT GLOB 'c*[^0-9]*')), auto INTEGER NOT NULL DEFAULT 1 CHECK (auto IN (0,1)), lane_order INTEGER, PRIMARY KEY (standup_id, column_name) ) STRICT, WITHOUT ROWID;
CREATE TABLE standup_config_history ( standup_id INTEGER NOT NULL REFERENCES standup(id) ON DELETE CASCADE, valid_from INTEGER NOT NULL, valid_to INTEGER, fingerprint TEXT NOT NULL, config_json TEXT NOT NULL, PRIMARY KEY (standup_id, valid_from) ) STRICT, WITHOUT ROWID;
CREATE TABLE standup_issue ( standup_id INTEGER NOT NULL REFERENCES standup(id) ON DELETE CASCADE, issue_id INTEGER NOT NULL REFERENCES issue(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('board','backlog')), rank_index INTEGER NOT NULL, PRIMARY KEY (standup_id, issue_id) ) STRICT, WITHOUT ROWID;
CREATE INDEX standup_issue_issue ON standup_issue(issue_id);
CREATE INDEX standup_issue_order ON standup_issue(standup_id, role, rank_index);
CREATE TABLE standup_issue_span ( standup_id INTEGER NOT NULL REFERENCES standup(id) ON DELETE CASCADE, issue_id INTEGER NOT NULL REFERENCES issue(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('board','backlog')), valid_from INTEGER NOT NULL, valid_to INTEGER, PRIMARY KEY (standup_id, issue_id, role, valid_from), CHECK (valid_to IS NULL OR valid_to > valid_from) ) STRICT, WITHOUT ROWID;
CREATE UNIQUE INDEX standup_issue_span_open ON standup_issue_span(standup_id, issue_id) WHERE valid_to IS NULL;
CREATE INDEX standup_issue_span_time ON standup_issue_span(standup_id, valid_from, valid_to);
CREATE TABLE "standup_lane" ( standup_id INTEGER NOT NULL REFERENCES standup(id) ON DELETE CASCADE, lane TEXT NOT NULL CHECK (lane IN ('todo','prog','review','qa') OR (lane GLOB 'c[1-9]*' AND lane NOT GLOB 'c*[^0-9]*')), walk_position INTEGER NOT NULL CHECK (walk_position >= 0), limit_days INTEGER NOT NULL CHECK (limit_days BETWEEN 0 AND 99), label TEXT CHECK (label IS NULL OR length(label) BETWEEN 1 AND 40), hue INTEGER CHECK (hue IS NULL OR hue BETWEEN 1 AND 8), CHECK ((lane GLOB 'c*') = (hue IS NOT NULL)), CHECK (lane NOT GLOB 'c*' OR label IS NOT NULL), PRIMARY KEY (standup_id, lane) ) STRICT, WITHOUT ROWID;
CREATE INDEX standup_order ON standup(position) WHERE deleted_at IS NULL;
CREATE TABLE standup_settings ( standup_id INTEGER PRIMARY KEY REFERENCES standup(id) ON DELETE CASCADE, rows_mode TEXT NOT NULL DEFAULT 'fit' CHECK (rows_mode IN ('fit','roomy')), unassigned_position TEXT NOT NULL DEFAULT 'last' CHECK (unassigned_position IN ('first','last','skip')), reshuffle_daily INTEGER NOT NULL DEFAULT 0 CHECK (reshuffle_daily IN (0,1)), shuffle_seed INTEGER NOT NULL DEFAULT 0, shuffle_date TEXT, pulse_days INTEGER NOT NULL DEFAULT 21 CHECK (pulse_days IN (7,14,21,28)), show_commits INTEGER NOT NULL DEFAULT 1 CHECK (show_commits IN (0,1)), show_prs INTEGER NOT NULL DEFAULT 1 CHECK (show_prs IN (0,1)), show_comments INTEGER NOT NULL DEFAULT 1 CHECK (show_comments IN (0,1)), shade_weekends INTEGER NOT NULL DEFAULT 1 CHECK (shade_weekends IN (0,1)), done_window TEXT NOT NULL DEFAULT 'sprint' CHECK (done_window IN ('sprint','14d','yesterday')), backlog_rows INTEGER NOT NULL DEFAULT 12 CHECK (backlog_rows BETWEEN 0 AND 50) , lane_seq INTEGER NOT NULL DEFAULT 0 CHECK (lane_seq >= 0), done_label TEXT CHECK (done_label IS NULL OR length(done_label) BETWEEN 1 AND 40)) STRICT;
CREATE TABLE standup_speaker ( standup_id INTEGER NOT NULL REFERENCES standup(id) ON DELETE CASCADE, account_id TEXT NOT NULL, display_name TEXT NOT NULL, position INTEGER NOT NULL, included INTEGER NOT NULL DEFAULT 1 CHECK (included IN (0,1)), added_manually INTEGER NOT NULL DEFAULT 0 CHECK (added_manually IN (0,1)), user_touched INTEGER NOT NULL DEFAULT 0 CHECK (user_touched IN (0,1)), last_seen_at INTEGER, created_at INTEGER NOT NULL, PRIMARY KEY (standup_id, account_id) ) STRICT, WITHOUT ROWID;
CREATE INDEX standup_speaker_order ON standup_speaker(standup_id, position);
CREATE TABLE standup_speaker_removed ( standup_id INTEGER NOT NULL REFERENCES standup(id) ON DELETE CASCADE, account_id TEXT NOT NULL, removed_at INTEGER NOT NULL, PRIMARY KEY (standup_id, account_id) ) STRICT, WITHOUT ROWID;
CREATE TABLE "standup_status_lane" ( standup_id INTEGER NOT NULL REFERENCES standup(id) ON DELETE CASCADE, status_id TEXT NOT NULL, status_name TEXT NOT NULL, column_name TEXT NOT NULL, lane TEXT NOT NULL CHECK (lane IN ('backlog','todo','prog','review','qa','done','hidden') OR (lane GLOB 'c[1-9]*' AND lane NOT GLOB 'c*[^0-9]*')), PRIMARY KEY (standup_id, status_id), FOREIGN KEY (standup_id, column_name) REFERENCES standup_column_map(standup_id, column_name) ON DELETE CASCADE ON UPDATE CASCADE ) STRICT, WITHOUT ROWID;
CREATE TABLE standup_sync_state ( standup_id INTEGER PRIMARY KEY REFERENCES standup(id) ON DELETE CASCADE, needs_sync INTEGER NOT NULL DEFAULT 1 CHECK (needs_sync IN (0,1)), last_attempt_at INTEGER, last_success_at INTEGER, last_full_at INTEGER, history_from INTEGER, backlog_total INTEGER NOT NULL DEFAULT -1, active_sprint_ids TEXT NOT NULL DEFAULT '[]' ) STRICT;
CREATE TABLE standup_ui_state ( standup_id INTEGER PRIMARY KEY REFERENCES standup(id) ON DELETE CASCADE, last_person TEXT, updated_at INTEGER NOT NULL , board_group TEXT NOT NULL DEFAULT 'assignee' CHECK (board_group IN ('assignee','status')), zoom INTEGER NOT NULL DEFAULT 100 CHECK (zoom IN (70,80,90,100,110,125,150,175,200))) STRICT;
CREATE TABLE status ( connection_id INTEGER NOT NULL REFERENCES connection(id) ON DELETE CASCADE, id TEXT NOT NULL, name TEXT NOT NULL, category TEXT NOT NULL CHECK (category IN ('new','indeterminate','done','undefined')), blocked_hint INTEGER NOT NULL DEFAULT 0 CHECK (blocked_hint IN (0,1)), PRIMARY KEY (connection_id, id) ) STRICT, WITHOUT ROWID;
CREATE TABLE status_change ( issue_id INTEGER NOT NULL REFERENCES issue(id) ON DELETE CASCADE, history_id TEXT NOT NULL, changed_at INTEGER NOT NULL, from_status_id TEXT NOT NULL, to_status_id TEXT NOT NULL, PRIMARY KEY (issue_id, history_id) ) STRICT, WITHOUT ROWID;
CREATE INDEX status_change_time ON status_change(issue_id, changed_at);
CREATE TABLE sync_log ( id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES sync_run(id) ON DELETE CASCADE, at INTEGER NOT NULL, level TEXT NOT NULL CHECK (level IN ('info','warn','error')), phase TEXT NOT NULL, message TEXT NOT NULL ) STRICT;
CREATE INDEX sync_log_run ON sync_log(run_id, id);
CREATE TABLE sync_run ( id INTEGER PRIMARY KEY, standup_id INTEGER NOT NULL REFERENCES standup(id) ON DELETE CASCADE, mode TEXT NOT NULL CHECK (mode IN ('incremental','full')), trigger TEXT NOT NULL CHECK (trigger IN ('manual','open','config')), status TEXT NOT NULL CHECK (status IN ('running','ok','partial','cancelled','failed')), started_at INTEGER NOT NULL, finished_at INTEGER, issues_scanned INTEGER NOT NULL DEFAULT 0, issues_hydrated INTEGER NOT NULL DEFAULT 0, requests INTEGER NOT NULL DEFAULT 0, throttled INTEGER NOT NULL DEFAULT 0, error_code TEXT, error_message TEXT, warnings TEXT NOT NULL DEFAULT '[]' ) STRICT;
CREATE INDEX sync_run_standup ON sync_run(standup_id, started_at DESC);
CREATE TABLE ticket_draft ( issue_id INTEGER PRIMARY KEY REFERENCES issue(id) ON DELETE CASCADE, body_text TEXT NOT NULL, mentions_json TEXT NOT NULL DEFAULT '[]', updated_at INTEGER NOT NULL ) STRICT;
CREATE TABLE ticket_field_pref ( connection_id INTEGER NOT NULL REFERENCES connection(id) ON DELETE CASCADE, field_id TEXT NOT NULL, position INTEGER, hidden INTEGER NOT NULL DEFAULT 0 CHECK (hidden IN (0,1)), PRIMARY KEY (connection_id, field_id), CHECK (position IS NOT NULL OR hidden = 1) ) STRICT, WITHOUT ROWID;
CREATE TABLE transition_cache ( issue_id INTEGER PRIMARY KEY REFERENCES issue(id) ON DELETE CASCADE, json TEXT NOT NULL, fetched_at INTEGER NOT NULL ) STRICT;
CREATE TABLE ui_state ( id INTEGER PRIMARY KEY CHECK (id = 1), last_standup_id INTEGER REFERENCES standup(id) ON DELETE SET NULL, last_view TEXT NOT NULL DEFAULT 'standup' CHECK (last_view IN ('standup','configure')), win_x INTEGER, win_y INTEGER, win_w INTEGER, win_h INTEGER, win_maximised INTEGER NOT NULL DEFAULT 0 CHECK (win_maximised IN (0,1)), updated_at INTEGER NOT NULL ) STRICT;
